$assignedSummary = is_array($_SESSION['core_flash_universe_summary'] ?? null) ? $_SESSION['core_flash_universe_summary'] : [];
unset($_SESSION['core_flash_universe_seed']);
unset($_SESSION['core_flash_universe_summary']);
function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Character Selection · CORE</title><link rel="stylesheet" href="<?=$base?>/player.css"></head><body><header class="topbar"><a class="brand" href="<?=$base?>/index.php"><span class="brand-mark">C</span><span>CORE <small>PLAYER PORTAL</small></span></a><nav class="portal-nav" aria-label="Player navigation"><a href="<?=$base?>/account.php">Account &amp; sign out</a></nav><span class="build-tag"><?=h($releaseVersion)?></span></header><main class="player-flow"><nav class="flow-steps" aria-label="Player setup progress"><span class="flow-step flow-step-complete">1 <small>Account</small></span><span class="flow-step flow-step-current" aria-current="step">2 <small>Characters</small></span><span class="flow-step">3 <small>Universe</small></span><span class="flow-step">4 <small>Play</small></span></nav><?php if($assignedSeed !== ''): ?><section class="notice success seed-result"><strong>Universe ready.</strong> Your universe seed: <code><?=h($assignedSeed)?></code><p>Keep this seed to recreate the same generated universe. <?=h((string)($assignedSummary['system_count']??''))?> star systems generated.</p></section><?php endif; ?><section class="welcome panel"><div class="eyebrow">PLAYER PORTAL · CHARACTER ROSTER</div><h1>Choose your <span>character.</span></h1><p>All characters associated with your account appear here. Characters can exist before they are assigned to a universe.</p><div class="flow-actions"><a class="action-link" href="<?=$base?>/character-create.php">＋ Create character</a></div></section>
<?php if(!$characters): ?><section class="panel empty-state"><h2>Your story starts here.</h2><p>You do not have any characters yet. Create your first character, then assign a universe before entering gameplay.</p><a class="action-link" href="<?=$base?>/character-create.php">Create your first character</a></section><?php else: ?><section class="roster-grid"><?php foreach($characters as $c): $uidUniverse=(string)($c['universe_id']??''); $u=$universes[$uidUniverse]??null; $universeSeed=(string)($u['seed']??$u['baseline']['seed']??''); $loc=$c['location']['system_id']??$c['current_system_id']??null; $systemName=$loc; $systemPreview=null; if($u && $loc) foreach(($u['baseline']['systems']??[]) as $sys) if(($sys['id']??null)===$loc){$systemPreview=$sys; $systemName=$sys['name']??$loc;break;} if($systemPreview){$previewGenerator=new \Core\\Modules\\Universe\\WorldGenerator();$systemPreview['worlds']=$previewGenerator->generateForSystem($universeSeed,$systemPreview);} ?><article class="panel character-card"><div class="character-card-visuals"><div class="character-portrait"><canvas class="character-portrait-canvas" aria-label="3D character portrait"></canvas><span>CHARACTER</span></div><div class="character-environment"><canvas class="character-universe-canvas" aria-label="3D view of assigned universe" data-systems="<?=h(json_encode($systemPreview ? [$systemPreview] : [], JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>"></canvas><span>UNIVERSE / LOCATION</span></div></div><div class="eyebrow"><?= $uidUniverse ? 'UNIVERSE ASSIGNED' : 'UNASSIGNED CHARACTER' ?></div><h2><?=h($c['name']??'Unnamed character')?></h2><p><?=h($c['species']??$c['species_id']??'Unknown species')?> · <?=h($c['role']??'No role')?></p><dl class="stats"><div><dt>Universe seed</dt><dd><?=h($universeSeed!==''?$universeSeed:($uidUniverse?'Seed unavailable for legacy universe':'Not assigned'))?></dd></div><div><dt>Last known location</dt><dd><?=h($systemName?:'Not recorded')?></dd></div></dl><?php if(!$uidUniverse): ?><a class="action-link" href="<?=$base?>/universe-create.php?character_id=<?=rawurlencode((string)$c['id'])?>">Create / assign universe</a><?php else: ?><a class="action-link" href="<?=$base?>/game.php?character_id=<?=rawurlencode((string)$c['id'])?>">Play</a><?php endif; ?></article><?php endforeach; ?></section><?php endif; ?><footer>CORE <?=h($releaseVersion)?> · Player workflow</footer></main><script src="https://cdn.babylonjs.com/babylon.js"></script><script src="<?=$base?>/character-roster-preview.js?v=<?=rawurlencode((string)$releaseVersion)?>"></script></body></html>